// ---- Reorder policy (dummy values, tune per client) ----
const REORDER_POINT = {
  "REBAR-12MM": 200,
  "CEMENT-25KG": 500,
  "TIMBER-50X100": 300,
  "INSULATION-50MM": 150,
  "BRICK-PALLET": 40
};
const TARGET_LEVEL = {
  "REBAR-12MM": 600,
  "CEMENT-25KG": 1500,
  "TIMBER-50X100": 900,
  "INSULATION-50MM": 450,
  "BRICK-PALLET": 120
};

// Field-name helpers — tolerant of both header styles
// (CleanWarehouse: warehouse_id/stock_qty/last_updated ; older map: ID/qty/update)
const whId       = r => (r.warehouse_id ?? r.ID ?? null);
const stockQty   = r => (r.stock_qty ?? r.qty);
const leadDays   = r => (r.lead_time_days ?? r.lead_time);
const supplierOf = r => ((r["supplier "] ?? r.supplier ?? "Unknown").toString().trim());

const rows = $input.all().map(i => i.json);

// A stock row has a warehouse id or a stock qty field.
const stockRows = rows.filter(r => ("warehouse_id" in r) || ("ID" in r) || ("stock_qty" in r) || ("qty" in r));
// A lead row has a lead time and no warehouse.
const leadRows  = rows.filter(r => (("lead_time_days" in r) || ("lead_time" in r)) && !("warehouse_id" in r) && !("stock_qty" in r) && !("ID" in r));

// Best (shortest) lead time + supplier per SKU.
const leadBySku = {};
for (const r of leadRows) {
  const raw = leadDays(r);
  const lt = (raw === "" || raw === null || raw === undefined) ? null : Number(raw);
  const existing = leadBySku[r.sku];
  if (!existing || (lt !== null && (existing.lead_time === null || lt < existing.lead_time))) {
    leadBySku[r.sku] = { supplier: supplierOf(r), lead_time: lt };
  }
}

const flagged = [];
for (const r of stockRows) {
  const sku = r.sku;
  const rp = REORDER_POINT[sku];
  if (rp === undefined) continue; // SKU not in policy, skip

  const raw = stockQty(r);
  const qty = (raw === "" || raw === null || raw === undefined || String(raw).toLowerCase() === "n/a")
    ? null : Number(raw);

  let status, orderQty;
  if (qty === null || isNaN(qty)) {
    status = "UNKNOWN";
    orderQty = null;
  } else if (qty <= rp) {
    status = qty === 0 ? "STOCKOUT" : "LOW";
    const target = TARGET_LEVEL[sku] || rp * 3;
    orderQty = Math.max(target - qty, 0);
  } else {
    continue; // healthy stock, skip
  }

  const lead = leadBySku[sku] || { supplier: "Unknown", lead_time: null };
  flagged.push({
    warehouse: whId(r),
    sku,
    on_hand: qty,
    reorder_point: rp,
    status,
    suggested_order_qty: orderQty,
    supplier: lead.supplier,
    lead_time_days: lead.lead_time,
    conflict: r.conflict === true || String(r.conflict).toLowerCase() === "true"
  });
}

if (flagged.length === 0) return []; // nothing low -> no alert sent

const rank = { "STOCKOUT": 0, "LOW": 1, "UNKNOWN": 2 };
flagged.sort((a, b) => (rank[a.status] - rank[b.status]) || String(a.warehouse).localeCompare(String(b.warehouse)));

const lines = flagged.map(f => {
  const icon = f.status === "STOCKOUT" ? ":red_circle:" : f.status === "LOW" ? ":large_orange_circle:" : ":white_circle:";
  const onHand = f.on_hand === null ? "unknown" : f.on_hand;
  const orderTxt = f.suggested_order_qty === null ? "verify stock manually" : `order ${f.suggested_order_qty}`;
  const leadTxt = f.lead_time_days === null ? "lead time n/a" : `${f.lead_time_days}d lead`;
  const conflictTxt = f.conflict ? "  :warning: data conflict" : "";
  return `${icon} *${f.sku}* @ ${f.warehouse} \u2014 on hand: ${onHand} (reorder \u2264 ${f.reorder_point}) \u2192 *${orderTxt}* from ${f.supplier} (${leadTxt})${conflictTxt}`;
});

const counts = flagged.reduce((a, f) => { a[f.status] = (a[f.status] || 0) + 1; return a; }, {});
const header = `:package: *Low-stock reorder alert* \u2014 ${flagged.length} item(s) flagged` +
  ` (${counts.STOCKOUT || 0} stockout, ${counts.LOW || 0} low, ${counts.UNKNOWN || 0} unknown)`;

const message = `${header}\n\n${lines.join("\n")}`;

return [{ json: { alert_count: flagged.length, message, items: flagged } }];
